+    let stdout = String::from_utf8_lossy(&output.stdout).into_owned();
+    assert_eq!(stderr.as_str(), "");
+    assert!(
+        stdout.contains("Usage"),
+        "expected clap help in stdout, got: {stdout}"
+    );
+
+    test.assert_no_leaks(&stderr);
+    Ok(())
+}
